/* @lc app=leetcode id=3578 lang=kotlin */ class Solution { fun countPartitions(nums: IntArray, k: Int): Int = 1_000_000_007L.let { M -> LongArray(nums.size + 1).also { it[0] = 1L }.let { dp -> LongArray(nums.size + 2).also { it[1] = 1L }.let { P -> java.util.ArrayDeque<Int>().let { mx -> java.util.ArrayDeque<Int>().let { mn -> nums.indices.fold(0) { l, i -> generateSequence { mx.peekLast()?.takeIf { nums[it] <= nums[i] } }.forEach { _ -> mx.pollLast() }.let { mx.addLast(i) }.let { generateSequence { mn.peekLast()?.takeIf { nums[it] >= nums[i] } }.forEach { _ -> mn.pollLast() }.let { mn.addLast(i) } }.let { generateSequence(l) { ll -> if (nums[mx.peekFirst()] - nums[mn.peekFirst()] > k) (ll + 1).also { nl -> (if (mx.peekFirst() < nl) mx.pollFirst() else null).let { if (mn.peekFirst() < nl) mn.pollFirst() } } else null }.last() }.also { l2 -> dp[i + 1] = ((P[i + 1] - P[l2]) % M + M) % M }.also { P[i + 2] = (P[i + 1] + dp[i + 1]) % M } }.let { dp[nums.size].toInt() } } } } } } }